            argv(&["git", "push", "origin", "main"]),
            argv(&["git", "reset"]),
            argv(&["git", "reset", "--hard"]),
            argv(&["git", "rebase", "main"]),
            argv(&["git", "filter-branch", "--all"]),
            argv(&["git", "filter-repo", "--path", "x"]),
            argv(&["git", "merge", "main"]),
            argv(&["git", "cherry-pick", "HEAD~1"]),
            argv(&["git", "revert", "HEAD"]),
