//! invisible to both directory listing and targeted reads.
//!
//! hānihi maintains its own `.ignore` file at the repo root (see
//! [`ensure_ignore_file`]): same syntax as `.gitignore`, but git-agnostic
//! and managed by hānihi. The repo's `.gitignore` is respected but never
//! written.

use std::fmt;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use ignore::gitignore::{Gitignore, GitignoreBuilder};
use ignore::{Match, Walk, WalkBuilder};

/// Maximum number of bytes [`SourceTree::read`] returns for one file.
pub const MAX_READ_BYTES: usize = 64 * 1024;

/// Marker line used to recognise an existing hānihi-managed `.ignore`.
const HANIHI_HEADER: &str = "# hānihi-managed ignore file (agent read policy)\n";

/// Programming languages hānihi can recognise and write templates for.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Language {
    /// Rust — detected by `Cargo.toml`.
    Rust,
    /// C or C++ — detected by `CMakeLists.txt`/`Makefile`/C-family sources.
    C,
}

impl Language {
    /// `.ignore`-syntax patterns for generated artifacts of this language.
    pub fn template(self) -> &'static str {
        match self {
            Language::Rust => "target/\n**/*.rs.bk\n",
            Language::C => {
                "build/\ncmake-build-*/\nCMakeFiles/\n\
                 *.o\n*.obj\n*.a\n*.so\n*.dylib\n*.exe\n\
                 *.gcda\n*.gcno\n\
                 a.out\n.cache/\n\
                 # compile_commands.json — sometimes committed; useful for the agent\n"
            }
        }
    }
}

/// Errors produced by [`SourceTree`].
#[derive(Debug)]
pub enum SourceError {
    /// No repository found (no `.git` at or above the start path).
    NotARepository(PathBuf),
    /// The requested path does not exist.
    NotFound(PathBuf),
    /// The requested path resolves outside the repository root.
    Escape(PathBuf),
    /// The requested path is excluded by an ignore rule.
    Ignored(PathBuf),
    /// I/O failure.
    Io(io::Error),
    /// Error from the `ignore` crate (parsing, walking).
    Ignore(ignore::Error),
}

impl fmt::Display for SourceError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SourceError::NotARepository(p) => {
                write!(f, "no git repository found at or above {}", p.display())
            }
            SourceError::NotFound(p) => write!(f, "no such path: {}", p.display()),
            SourceError::Escape(p) => write!(f, "path escapes the repository: {}", p.display()),
            SourceError::Ignored(p) => write!(f, "path is ignored: {}", p.display()),
            SourceError::Io(e) => write!(f, "io error: {e}"),
            SourceError::Ignore(e) => write!(f, "ignore error: {e}"),
        }
    }
}

impl std::error::Error for SourceError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            SourceError::Io(e) => Some(e),
            SourceError::Ignore(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for SourceError {
    fn from(e: io::Error) -> Self {
        SourceError::Io(e)
    }
}

impl From<ignore::Error> for SourceError {
    fn from(e: ignore::Error) -> Self {
        SourceError::Ignore(e)
    }
}

/// A git repository the agent may read, filtered by ignore rules.
#[derive(Debug)]
pub struct SourceTree {
    root: PathBuf,
    matcher: Gitignore,
}

impl SourceTree {
    /// Locate the repository containing the current directory and open it.
    pub fn open() -> Result<Self, SourceError> {
        let cwd = std::env::current_dir().map_err(SourceError::Io)?;
        let root = find_repo_root(&cwd).ok_or(SourceError::NotARepository(cwd))?;
        Self::open_at(&root)
    }

    /// Open the repository rooted at `root` (must contain `.git`).
    pub fn open_at(root: &Path) -> Result<Self, SourceError> {
        let root = root.canonicalize().map_err(SourceError::Io)?;
        if !root.join(".git").exists() {
            return Err(SourceError::NotARepository(root));
        }
        // Maintain `.ignore` first so the matcher below picks it up.
        ensure_ignore_file(&root)?;
        let matcher = build_matcher(&root)?;
        Ok(Self { root, matcher })
    }

    /// The canonical repository root.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Whether `abs` (an absolute path) is excluded by ignore rules.
    /// Paths outside the repository count as ignored.
    pub fn is_ignored(&self, abs: &Path) -> bool {
        let Ok(rel) = abs.strip_prefix(&self.root) else {
            return true;
        };
        let is_dir = abs.is_dir();
        matches!(
            self.matcher.matched_path_or_any_parents(rel, is_dir),
            Match::Ignore(_)
        )
    }

    /// Iterate visible entries under `rel`, honouring ignore rules and a
    /// recursion `max_depth` (0 = just the directory itself). The walker
    /// never descends into `.git`.
    pub fn walk(&self, rel: &Path, max_depth: usize) -> Result<Walk, SourceError> {
        let base = self.resolve(rel)?;
        Ok(WalkBuilder::new(&base)
            .standard_filters(true)
            .hidden(false) // dotfiles stay visible; ignore rules are the policy
            .require_git(true)
            .max_depth(Some(max_depth))
            .sort_by_file_path(|a, b| a.cmp(b))
            .filter_entry(|e| e.file_name() != ".git")
            .build())
    }

    /// Read a text file under `rel`, honouring ignore rules and the size
    /// cap. Returns the (possibly truncated) contents.
    pub fn read(&self, rel: &Path) -> Result<String, SourceError> {
        let canon = self.resolve(rel)?;
        if !canon.is_file() {
            return Err(SourceError::NotFound(rel.to_path_buf()));
        }
        if self.is_ignored(&canon) {
            return Err(SourceError::Ignored(rel.to_path_buf()));
        }
        let bytes = fs::read(&canon).map_err(SourceError::Io)?;
        let text = String::from_utf8_lossy(&bytes);
        let cut = text.floor_char_boundary(MAX_READ_BYTES);
        let mut out = String::with_capacity(cut + 64);
        out.push_str(&text[..cut]);
        if bytes.len() > MAX_READ_BYTES {
            let note = format!("\n…[truncated, {} bytes total]", bytes.len());
            out.push_str(&note);
        }
        Ok(out)
    }

    /// Resolve `rel` inside the repository root to a canonical absolute
    /// path, refusing escapes.
    pub(crate) fn resolve(&self, rel: &Path) -> Result<PathBuf, SourceError> {
        let abs = self.root.join(rel);
        let canon = abs
            .canonicalize()
            .map_err(|_| SourceError::NotFound(rel.to_path_buf()))?;
        if !canon.starts_with(&self.root) {
            return Err(SourceError::Escape(rel.to_path_buf()));
        }
        Ok(canon)
    }

    /// Resolve a repository-relative path for writing, refusing escapes.
    ///
    /// Unlike [`SourceTree::resolve`], the target need not exist yet: the
    /// nearest existing ancestor is canonicalized (resolving any symlinks)
    /// and the non-existent tail is re-appended. Absolute paths and any
    /// `..` component are refused before touching the filesystem.
    pub fn resolve_for_write(&self, rel: &Path) -> Result<PathBuf, SourceError> {
        for comp in rel.components() {
            if matches!(
                comp,
                std::path::Component::ParentDir
                    | std::path::Component::RootDir
                    | std::path::Component::Prefix(_)
            ) {
                return Err(SourceError::Escape(rel.to_path_buf()));
            }
        }

        let abs = self.root.join(rel);
        let mut existing = abs.clone();
        let mut tail: Vec<std::ffi::OsString> = Vec::new();
        loop {
            match existing.canonicalize() {
                Ok(canon) => {
                    let mut resolved = canon;
                    for comp in tail.iter().rev() {
                        resolved.push(comp);
                    }
                    if !resolved.starts_with(&self.root) {
                        return Err(SourceError::Escape(rel.to_path_buf()));
                    }
                    return Ok(resolved);
                }
                Err(_) => {
                    let Some(name) = existing.file_name() else {
                        return Err(SourceError::NotFound(rel.to_path_buf()));
                    };
                    tail.push(name.to_os_string());
                    if !existing.pop() {
                        return Err(SourceError::NotFound(rel.to_path_buf()));
                    }
                }
            }
        }
    }
}

/// Nearest ancestor of `start` that contains `.git` (a directory, or a
/// file — the latter covers worktrees).
fn find_repo_root(start: &Path) -> Option<PathBuf> {
    let mut dir = Some(start);
    while let Some(d) = dir {
        if d.join(".git").exists() {
            return Some(d.to_path_buf());
        }
        dir = d.parent();
    }
    None
}

/// Build the ignore matcher from `.gitignore`, `.ignore`, and
/// `.git/info/exclude` (existing files only — `GitignoreBuilder::add`
/// errors on missing files).
fn build_matcher(root: &Path) -> Result<Gitignore, SourceError> {
    let mut builder = GitignoreBuilder::new(root);
    for name in [".gitignore", ".ignore"] {
        let path = root.join(name);
        if path.exists()
            && let Some(err) = builder.add(&path)
        {
            return Err(SourceError::Ignore(err));
        }
    }
    let exclude = root.join(".git/info/exclude");
    if exclude.exists()
        && let Some(err) = builder.add(&exclude)
    {
        return Err(SourceError::Ignore(err));
    }
    builder.build().map_err(SourceError::Ignore)
}

/// Ensure the repo has a `.ignore` file describing hānihi's read policy.
///
/// Never clobbers existing content: the language template header is only
/// prepended when absent, and everything the user wrote is preserved.
fn ensure_ignore_file(root: &Path) -> Result<(), SourceError> {
    let path = root.join(".ignore");
    let existing = if path.exists() {
        fs::read_to_string(&path).map_err(SourceError::Io)?
    } else {
        String::new()
    };

    let mut changed = false;
    let mut content = existing;
    if !content.contains(HANIHI_HEADER) {
        let mut tpl = String::from(HANIHI_HEADER);
        for lang in detect_languages(root) {
            tpl.push_str(lang.template());
        }
        tpl.push('\n');
        content = format!("{tpl}{content}");
        changed = true;
    }
    if changed {
        fs::write(&path, content).map_err(SourceError::Io)?;
    }
    Ok(())
}

/// Detect programming languages from marker files and source extensions,
/// scanning up to two levels deep (catches workspace members).
fn detect_languages(root: &Path) -> Vec<Language> {
    let mut langs = Vec::new();
    let mut has_c = false;
    let walker = WalkBuilder::new(root)
        .standard_filters(true)
        .hidden(false)
        .require_git(true)
        .max_depth(Some(2))
        .build();
    for entry in walker.flatten() {
        let path = entry.path();
        if path == root {
            continue;
        }
        let name = entry.file_name().to_string_lossy();
        match name.as_ref() {
            "Cargo.toml" => push_lang(&mut langs, Language::Rust),
            "CMakeLists.txt" | "Makefile" | "meson.build" => has_c = true,
            _ => {
                let ext = path
                    .extension()
                    .and_then(|e| e.to_str())
                    .unwrap_or("")
                    .to_ascii_lowercase();
                if matches!(
                    ext.as_str(),
                    "c" | "h" | "cpp" | "cc" | "cxx" | "hpp" | "hh"
                ) {
                    has_c = true;
                }
            }
        }
    }
    if has_c {
        push_lang(&mut langs, Language::C);
    }
    langs
}

fn push_lang(langs: &mut Vec<Language>, lang: Language) {
    if !langs.contains(&lang) {
        langs.push(lang);
    }
}

#[cfg(test)]
pub(crate) mod testutil {
    use super::*;
    use std::fs;
    use std::sync::Arc;

    /// Throwaway git repo with an ignored `target/` dir.
    pub(crate) struct Fixture {
        pub(crate) dir: PathBuf,
    }

    impl Fixture {
        pub(crate) fn new() -> Self {
            let dir = std::env::temp_dir().join(format!("hanihi-src-{}", uuid::Uuid::new_v4()));
            fs::create_dir_all(dir.join(".git")).unwrap();
            fs::create_dir_all(dir.join("src")).unwrap();
            fs::create_dir_all(dir.join("target/debug")).unwrap();
            fs::write(dir.join(".gitignore"), "target/\n").unwrap();
            fs::write(dir.join("Cargo.toml"), "[package]\nname = \"fixture\"\n").unwrap();
            fs::write(dir.join("src/main.rs"), "fn main() {}\n").unwrap();
            fs::write(dir.join("target/debug/junk.rs"), "junk\n").unwrap();
            Self { dir }
        }

        pub(crate) fn tree(&self) -> Arc<SourceTree> {
            Arc::new(SourceTree::open_at(&self.dir).expect("fixture is a git repo"))
        }
    }

    impl Drop for Fixture {
        fn drop(&mut self) {
            fs::remove_dir_all(&self.dir).unwrap_or(());
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    #[test]
    fn walk_excludes_ignored_paths() {
        let fx = testutil::Fixture::new();
        let tree = fx.tree();
        let paths: Vec<PathBuf> = tree
            .walk(Path::new("."), 4)
            .unwrap()
            .filter_map(Result::ok)
            .map(|e| e.path().to_path_buf())
            .collect();
        assert!(paths.iter().any(|p| p.ends_with("src/main.rs")));
        assert!(paths.iter().any(|p| p.ends_with("Cargo.toml")));
        assert!(!paths.iter().any(|p| p.ends_with("target")));
        assert!(!paths.iter().any(|p| p.ends_with("junk.rs")));
        assert!(
            !paths
                .iter()
                .any(|p| p.components().any(|c| c.as_os_str() == ".git"))
        );
    }

    #[test]
    fn walk_is_shallow_at_depth_one() {
        let fx = testutil::Fixture::new();
        let tree = fx.tree();
        let paths: Vec<PathBuf> = tree
            .walk(Path::new("."), 1)
            .unwrap()
            .filter_map(Result::ok)
            .map(|e| e.path().to_path_buf())
            .collect();
        // src/ is listed, src/main.rs is not.
        assert!(paths.iter().any(|p| p.ends_with("src")));
        assert!(!paths.iter().any(|p| p.ends_with("src/main.rs")));
    }

    #[test]
    fn read_honours_ignore_rules() {
        let fx = testutil::Fixture::new();
        let tree = fx.tree();
        let main = tree.read(Path::new("src/main.rs")).unwrap();
        assert!(main.contains("fn main"));
        match tree.read(Path::new("target/debug/junk.rs")) {
            Err(SourceError::Ignored(_)) => {}
            other => panic!("expected Ignored, got {other:?}"),
        }
    }

    #[test]
    fn read_refuses_escapes() {
        let fx = testutil::Fixture::new();
        let tree = fx.tree();
        let name = format!("hanihi-outside-{}", uuid::Uuid::new_v4());
        let outside = std::env::temp_dir().join(&name);
        fs::write(&outside, "secret").unwrap();
        let rel = Path::new("..").join(&name);
        match tree.read(&rel) {
            Err(SourceError::Escape(_)) => {}
            other => panic!("expected Escape, got {other:?}"),
        }
        fs::remove_file(&outside).unwrap_or(());
    }

    #[test]
    fn read_truncates_large_files() {
        let fx = testutil::Fixture::new();
        let tree = fx.tree();
        fs::write(fx.dir.join("big.rs"), "x".repeat(MAX_READ_BYTES + 4096)).unwrap();
        let out = tree.read(Path::new("big.rs")).unwrap();
        assert!(out.contains("[truncated"));
        assert!(out.len() < MAX_READ_BYTES + 4096);
    }

    #[test]
    fn open_requires_a_repository() {
        let dir = std::env::temp_dir().join(format!("hanihi-norepo-{}", uuid::Uuid::new_v4()));
        fs::create_dir_all(&dir).unwrap();
        let err = SourceTree::open_at(&dir).unwrap_err();
        assert!(matches!(err, SourceError::NotARepository(_)));
        fs::remove_dir_all(&dir).unwrap_or(());
    }

    #[test]
    fn find_repo_root_walks_up() {
        let fx = testutil::Fixture::new();
        assert_eq!(find_repo_root(&fx.dir.join("src")), Some(fx.dir.clone()));
    }

    #[test]
    fn find_repo_root_returns_none_outside_repos() {
        let dir = std::env::temp_dir().join(format!("hanihi-norepo-{}", uuid::Uuid::new_v4()));
        fs::create_dir_all(&dir).unwrap();
        assert_eq!(find_repo_root(&dir), None);
        fs::remove_dir_all(&dir).unwrap_or(());
    }

    #[test]
    fn ensure_ignore_file_bootstraps_rust_template() {
        let fx = testutil::Fixture::new();
        fx.tree(); // open_at runs ensure_ignore_file
        let content = fs::read_to_string(fx.dir.join(".ignore")).unwrap();
        assert!(content.contains(HANIHI_HEADER));
        assert!(content.contains("target/"));
    }

    #[test]
    fn ensure_ignore_file_preserves_user_content() {
        let fx = testutil::Fixture::new();
        fs::write(fx.dir.join(".ignore"), "vendor/\n").unwrap();
        fx.tree();
        let content = fs::read_to_string(fx.dir.join(".ignore")).unwrap();
        assert!(content.contains("vendor/"));
        assert!(content.contains(HANIHI_HEADER));
        // Opening again must not duplicate the template.
        fx.tree();
        let content2 = fs::read_to_string(fx.dir.join(".ignore")).unwrap();
        assert_eq!(content, content2);
    }
}

//! # hanihi-cli
//!
//! REPL front-end for the agent harness: reedline line editor on top of
//! [`hanihi_core::Agent`]. Supports sessions (`--session` / `--new-session`),
//! one-shot turns (`--once`), and MCP stdio servers.

mod highlight;
mod ui;

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use crate::highlight::MonoHighlighter;
use clap::Parser;
use hanihi_core::agent::Agent;
use hanihi_core::error::AgentError;
use hanihi_core::session::SessionManager;
use hanihi_core::{
    McpClient, SourceTree, StreamEvent, builtin_apply_patch, builtin_get_time, builtin_grep,
    builtin_list_dir, builtin_read_file, builtin_read_session_log, builtin_run_command,
    builtin_run_command_write, builtin_write_file, connect_chat_model_with_prompt, debug,
};
use nu_ansi_term::Color;
use reedline::{DefaultPrompt, FileBackedHistory, Reedline, Signal};
use rig::completion::CompletionModel;
use tracing_subscriber::EnvFilter;

pub use hanihi_core::agent::{TurnSummary, connect_chat_model};

use crate::ui::{print_coloured, println_coloured};

const DEFAULT_WORKING_DIR: &str = "./working";
/// Default cap on model turns per request. Effectively unlimited: a sane
/// upper bound so runaway tool-call loops still terminate, but far above any
/// realistic working session.
const DEFAULT_MAX_TURNS: usize = 10;
/// Default cap on model turns in task mode (long-horizon self-improvement).
const TASK_MAX_TURNS: usize = 10;

#[derive(Parser, Debug)]
#[command(
    name = "hānihi",
    version,
    about = "Rust agent harness: rig + rmcp + reedline"
)]
struct Args {
    /// OpenAI-compatible chat completions base URL.
    #[arg(
        long,
        env = "LLM_BASE_URL",
        default_value = "https://api.deepseek.com/v1"
    )]
    base_url: String,

    /// API key (or set LLM_API_KEY).
    #[arg(long, env = "LLM_API_KEY")]
    api_key: Option<String>,

    /// Model name (or set LLM_MODEL).
    #[arg(long, env = "LLM_MODEL", default_value = "deepseek-chat")]
    model: String,

    /// Working directory for sessions (default: ./working, relative to cwd).
    #[arg(long, env = "HANIHI_WORKING_DIR", default_value = DEFAULT_WORKING_DIR)]
    working_dir: PathBuf,

    /// Use an existing session by name (default: "default-session").
    #[arg(long, default_value = "default-session")]
    session: String,

    /// Create a new session with this name and use it.
    #[arg(long, conflicts_with = "session")]
    new_session: Option<String>,

    /// MCP stdio server command(s) to attach, e.g.
    /// `--mcp-command "./target/debug/hanihi-mcp-server"`. May be repeated.
    #[arg(long = "mcp-command", value_name = "CMD")]
    mcp_commands: Vec<String>,

    /// Run a single turn and exit (no REPL).
    #[arg(long, value_name = "PROMPT")]
    once: Option<String>,

    /// Register write tools (apply_patch, write_file) — enables editing the
    /// enclosing repository. Off by default; analysis and build tools are
    /// always on.
    #[arg(long)]
    write: bool,

    /// Run a single long-horizon turn with the task-mode system prompt
    /// (workflow gates: fmt → test → build → clippy → commit). Takes
    /// precedence over --once.
    #[arg(long, value_name = "PROMPT")]
    task: Option<String>,

    /// Maximum model turns per request (default: 1000; task mode: 1000).
    #[arg(long)]
    max_turns: Option<usize>,

    /// Append this text to the system prompt. Repeatable. When used with an
    /// existing session, the appended text is persisted to the session so it
    /// applies on future resumes too.
    #[arg(long = "prompt", value_name = "TEXT")]
    prompt_append: Vec<String>,

    /// Append the content of this file to the system prompt. Repeatable.
    /// When used with an existing session, the appended content is persisted
    /// to the session so it applies on future resumes too.
    #[arg(long = "prompt-file", value_name = "PATH")]
    prompt_files: Vec<PathBuf>,

    /// Replace the entire system prompt with the additions (no base prompt
    /// is prepended). For use with --session to rewrite the stored prompt,
    /// or with --new-session to override the default. Mutually exclusive
    /// with --prompt/--prompt-file append semantics (see below).
    #[arg(long)]
    new_prompt: bool,
}

/// Extract a short provider name from a base URL hostname.
fn provider_from_url(url: &str) -> &str {
    // Strip scheme.
    let host = url
        .trim_start_matches("https://")
        .trim_start_matches("http://")
        .split('/')
        .next()
        .unwrap_or("unknown");
    // e.g. "api.deepseek.com" -> "deepseek", "api.openai.com" -> "openai"
    host.trim_start_matches("api.")
        .trim_start_matches("api-")
        .split('.')
        .next()
        .unwrap_or("unknown")
}

/// Read the given prompt files and return their concatenated contents.
fn read_prompt_files(paths: &[PathBuf]) -> Result<String, AgentError> {
    let mut out = String::new();
    for path in paths {
        let content = fs::read_to_string(path)?;
        if !out.is_empty() {
            out.push('\n');
        }
        out.push_str(&content);
    }
    Ok(out)
}

/// Read a single file's contents for use as a prompt, resolved against the
/// given base directory when the path is not absolute.
fn read_prompt_file(base: &Path, path: &str) -> Result<String, AgentError> {
    let resolved = if Path::new(path).is_absolute() {
        PathBuf::from(path)
    } else {
        base.join(path)
    };
    if !resolved.is_file() {
        return Err(AgentError::Io(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            format!("no such file: {}", resolved.display()),
        )));
    }
    fs::read_to_string(&resolved).map_err(AgentError::Io)
}

/// Concatenate the explicit additions (`--prompt` strings and the contents
/// of `--prompt-file` files) into one block.
fn collect_extras(
    prompt_appends: &[String],
    prompt_files: &[PathBuf],
) -> Result<String, AgentError> {
    let file_text = read_prompt_files(prompt_files)?;
    let mut parts: Vec<String> = Vec::new();
    parts.extend(prompt_appends.iter().cloned());
    if !file_text.is_empty() {
        parts.push(file_text);
    }
    Ok(parts.join("\n\n"))
}

/// Whether any explicit prompt additions were supplied.
fn has_extras(prompt_appends: &[String], prompt_files: &[PathBuf]) -> bool {
    !prompt_appends.is_empty() || !prompt_files.is_empty()
}

/// Read the system prompt stored in an existing session's session.json.
fn stored_session_prompt(working_dir: &std::path::Path, session_name: &str) -> Option<String> {
    let meta_path = working_dir
        .join("sessions")
        .join(session_name)
        .join("session.json");
    let bytes = fs::read_to_string(meta_path).ok()?;
    let meta: serde_json::Value = serde_json::from_str(&bytes).ok()?;
    meta.get("system_prompt")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
}

/// Persist a system prompt into an existing session's session.json. Reads
/// the file, updates the field, writes it back.
fn write_session_prompt(
    working_dir: &std::path::Path,
    session_name: &str,
    prompt: &str,
) -> Result<(), AgentError> {
    let meta_path = working_dir
        .join("sessions")
        .join(session_name)
        .join("session.json");
    let bytes = fs::read(&meta_path).map_err(AgentError::Io)?;
    let mut meta: serde_json::Value = serde_json::from_slice(&bytes).map_err(AgentError::Json)?;
    meta["system_prompt"] = serde_json::Value::String(prompt.to_string());
    fs::write(&meta_path, serde_json::to_string_pretty(&meta)?).map_err(AgentError::Io)?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), AgentError> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .init();

    let args = Args::parse();
    let api_key = args
        .api_key
        .filter(|k| !k.is_empty())
        .ok_or(AgentError::MissingApiKey)?;

    // Resolve working directory relative to cwd.
    let working_dir = if args.working_dir.is_absolute() {
        args.working_dir.clone()
    } else {
        std::env::current_dir()?.join(&args.working_dir)
    };

    let mut mgr = SessionManager::new(&working_dir);
    let provider = provider_from_url(&args.base_url);

    let task_mode = args.task.is_some();
    let base_prompt: &str = if task_mode {
        hanihi_core::agent::TASK_SYSTEM_PROMPT
    } else {
        hanihi_core::agent::DEFAULT_SYSTEM_PROMPT
    };

    // Determine session name and whether to auto-create.
    let (session_name, is_new) = if let Some(ref name) = args.new_session {
        (name.clone(), true)
    } else {
        let name = args.session.clone();
        // Auto-create default-session if it doesn't exist.
        let is_new = name == "default-session" && !mgr.exists(&name);
        (name, is_new)
    };

    let had_extras = has_extras(&args.prompt_append, &args.prompt_files);

    // Resolve the system prompt this invocation will use, and whether it
    // must be persisted back to the session's metadata.
    //
    // Prompt resolution rules:
    //  - `--new-prompt` on any session: the additions (collected from
    //    --prompt / --prompt-file) become the ENTIRE prompt. On an existing
    //    session this replaces and persists the stored prompt.
    //  - Otherwise `--prompt` / `--prompt-file` append to the base prompt
    //    (new session) or to the stored prompt (existing session), and the
    //    appended result is persisted so it survives a resume.
    //  - With no additions at all, the existing stored prompt is used
    //    unchanged (or the base prompt for a fresh session).
    let (session_prompt, do_persist) = if args.new_prompt {
        // Replace/set the entire prompt from the additions only.
        let prompt = collect_extras(&args.prompt_append, &args.prompt_files)?;
        let effective = if prompt.trim().is_empty() {
            // --new-prompt with nothing supplied: use base as the new prompt.
            base_prompt.to_string()
        } else {
            prompt
        };
        if is_new {
            (effective, false) // creation persists it
        } else {
            (effective, true) // replace + persist the stored prompt
        }
    } else if is_new {
        // Fresh session: base + any appends. persisted by creation.
        let prompt = if had_extras {
            let extras = collect_extras(&args.prompt_append, &args.prompt_files)?;
            format!("{base_prompt}\n\n{extras}")
        } else {
            base_prompt.to_string()
        };
        (prompt, false)
    } else if had_extras {
        // Existing session with appends: stored + extras, persisted.
        let stored = stored_session_prompt(&working_dir, &session_name)
            .unwrap_or_else(|| base_prompt.to_string());
        let extras = collect_extras(&args.prompt_append, &args.prompt_files)?;
        let prompt = format!("{stored}\n\n{extras}");
        (prompt, true)
    } else {
        // Existing session, no additions: use stored prompt unchanged.
        let stored = stored_session_prompt(&working_dir, &session_name)
            .unwrap_or_else(|| base_prompt.to_string());
        (stored, false)
    };

    // Create or open the session.
    if is_new {
        if session_name == "default-session" {
            mgr.create_default(&args.model, &session_prompt)
                .map_err(|e| AgentError::Rig(e.to_string()))?;
            println!("auto-created session 'default-session'");
        } else {
            mgr.create(&session_name, &args.model, &session_prompt)
                .map_err(|e| AgentError::Rig(e.to_string()))?;
            println!("created session '{session_name}'");
        }
    } else {
        mgr.open(&session_name)
            .map_err(|e| AgentError::Rig(e.to_string()))?;
        if do_persist {
            write_session_prompt(&working_dir, &session_name, &session_prompt)?;
            if args.new_prompt {
                println!("session '{session_name}' system prompt replaced");
            } else {
                println!("session '{session_name}' system prompt extended");
            }
        }
    }

    // Build the agent with the resolved system prompt.
    let mut agent = connect_chat_model_with_prompt(
        args.base_url.clone(),
        api_key.clone(),
        args.model.clone(),
        &session_prompt,
    )?;
    agent.set_max_turns(args.max_turns.unwrap_or(if task_mode {
        TASK_MAX_TURNS
    } else {
        DEFAULT_MAX_TURNS
    }));
    agent.add_tool(builtin_get_time());

    // Source-tree tools: read/list/grep/run-command over the enclosing git
    // repository, plus a window into this session's own event log. Ignore
    // rules (.gitignore, .ignore) filter what the agent can see. Write tools
    // (apply_patch, write_file) are registered only with --write.
    match SourceTree::open() {
        Ok(tree) => {
            let tree = Arc::new(tree);
            let traces_dir = working_dir.join("traces").join(&session_name);
            let log_path = working_dir
                .join("sessions")
                .join(&session_name)
                .join("events.jsonl");
            agent.add_tool(builtin_read_file(tree.clone()));
            agent.add_tool(builtin_list_dir(tree.clone()));
            agent.add_tool(builtin_grep(tree.clone()));
            if args.write {
                agent.add_tool(builtin_run_command_write(tree.clone(), traces_dir));
            } else {
                agent.add_tool(builtin_run_command(tree.clone(), traces_dir));
            }
            agent.add_tool(builtin_read_session_log(log_path));
            if args.write {
                agent.add_tool(builtin_apply_patch(tree.clone()));
                agent.add_tool(builtin_write_file(tree));
            }
        }
        Err(e) => println!("source tools disabled (no git repository): {e}"),
    }

    for command in &args.mcp_commands {
        debug::log_to_file("command from args.mcp_commands: ", command);
        let parts: Vec<String> = command.split_whitespace().map(String::from).collect();
        let (program, rest) = parts.split_first().ok_or_else(|| AgentError::Tool {
            name: "<mcp>".into(),
            message: "empty --mcp-command".into(),
        })?;
        let client = McpClient::connect_stdio(program, rest).await?;
        let tools = client.tool_defs().await?;
        let count = tools.len();
        for tool in tools {
            agent.add_tool(tool);
        }
        println!("attached MCP server '{program}': {count} tool(s)");
    }

    // Get a mutable reference to the open session so we can read its turn
    // count for the "session renewed" metadata below.
    let session = mgr
        .open(&session_name)
        .map_err(|_e| AgentError::Rig("failed to re-open session".into()))?;

    // Replay prior turns from the event log so the agent remembers
    // previous conversations in this session.
    let mut prior_turns = None;
    match session.replay_history() {
        Ok(history) if !history.is_empty() => {
            let msg_count = history.len();
            agent.set_history(history);
            println!("replayed {msg_count} messages from prior session");
        }
        Ok(_) => {} // empty history, nothing to replay
        Err(e) => {
            tracing::warn!("failed to replay session history: {e}");
        }
    }
    // How many turns has this session accumulated so far (including from
    // prior sessions)? Use the session's own counter; it is monotonically
    // increasing across restarts of the same session name.
    if let Ok(turns) = session.total_turns() {
        prior_turns = Some(turns);
    }

    println!(
        "agent ready: model={} tools={} session='{session_name}' max_turns={}{}",
        args.model,
        agent.tool_count(),
        agent.max_turns(),
        if args.write {
            " (write tools enabled)"
        } else {
            ""
        },
    );
    if let Some(t) = prior_turns {
        println!(
            "session '{}' renewed: total turns so far = {t}",
            session_name
        );
    }
    println!("system prompt: {} bytes", session_prompt.len());

    let prompt = args.task.clone().or_else(|| args.once.clone());
    if let Some(prompt) = prompt {
        let mut rx = session
            .run_streaming(&mut agent, provider, &args.model, &prompt)
            .await
            .map_err(|e| AgentError::Rig(e.to_string()))?;

        while let Some(event) = rx.recv().await {
            match event {
                StreamEvent::TextDelta { text } => print_coloured!("{text}"),
                StreamEvent::ToolCallStart { name, .. } => print_coloured!("\n[🔧 {name}"),
                StreamEvent::ToolCallArgs { .. } => {}
                StreamEvent::ToolCallReady { .. } => {}
                StreamEvent::ToolResult { .. } => println_coloured!(" ✅]"),
                StreamEvent::CompletionRequest { .. } | StreamEvent::CompletionResponse { .. } => {}
                StreamEvent::TurnComplete { summary } => {
                    println!();
                    println_coloured!(
                        "[turn {} | tool calls: {} | tokens: {} in / {} out | max_turns: {}]",
                        session.turn,
                        summary.tool_calls,
                        summary.usage.input_tokens,
                        summary.usage.output_tokens,
                        agent.max_turns()
                    );
                    agent.set_history(summary.final_history);
                    break;
                }
                StreamEvent::Error { message } => {
                    eprintln!();
                    eprintln!("error: {message}");
                    break;
                }
            }
        }
        mgr.close(&session_name)
            .map_err(|e| AgentError::Rig(e.to_string()))?;
        return Ok(());
    }

    let cwd = std::env::current_dir().map_err(AgentError::Io)?;
    repl(session, agent, provider, &args.model, &cwd, &working_dir).await?;

    mgr.close(&session_name)
        .map_err(|e| AgentError::Rig(e.to_string()))?;
    Ok(())
}

/// Render the per-turn completion footer shown after (and by /session for) a turn.
fn turn_footer(
    model: &str,
    turn: u64,
    tool_calls: usize,
    tokens_in: u64,
    tokens_out: u64,
    max_turns: usize,
) -> String {
    format!(
        "[model: {model} turn {turn} | tool calls: {tool_calls} | tokens: {tokens_in} in / {tokens_out} out | max_turns: {max_turns}]"
    )
}

/// Interactive readline loop.
async fn repl<M: CompletionModel + 'static>(
    session: &mut hanihi_core::session::Session,
    mut agent: Agent<M>,
    provider: &str,
    model_name: &str,
    cwd: &Path,
    working_dir: &Path,
) -> Result<(), AgentError> {
    let history_path = session.root().join("history.txt");
    let history: Box<dyn reedline::History> =
        match FileBackedHistory::with_file(10_000, history_path) {
            Ok(h) => Box::new(h),
            Err(e) => {
                eprintln!("history file disabled: {e}");
                Box::new(FileBackedHistory::new(10_000).expect("in-memory history"))
            }
        };
    let edit_mode = reedline::Emacs::default();
    let mut editor = Reedline::create()
        .with_edit_mode(Box::new(edit_mode))
        .with_history(history)
        .with_highlighter(Box::new(MonoHighlighter::new(Color::Cyan)));
    let prompt = DefaultPrompt::default();
    let mut last_summary: Option<TurnSummary> = None;
    loop {
        match editor.read_line(&prompt) {
            Ok(Signal::Success(line) | Signal::HostCommand(line)) => {
                let line = line.trim().to_string();
                match line.as_str() {
                    "" => continue,
                    "/quit" | "/exit" => break,
                    "/help" => {
                        println!(
                            "commands: /help /tools /clear /session /file /quit — anything else is sent to the model"
                        );
                        continue;
                    }
                    "/tools" => {
                        for def in agent.tool_definitions() {
                            println!("- {}: {}", def.name, def.description);
                        }
                        continue;
                    }
                    "/clear" => {
                        agent.clear_history();
                        println!("history cleared");
                        continue;
                    }
                    "/session" => {
                        println!(
                            "session: '{}' (id={}) turn={} max_turns={}",
                            session.name,
                            session.id,
                            session.turn,
                            agent.max_turns()
                        );
                        if let Some(s) = &last_summary {
                            println!(
                                "{}",
                                turn_footer(
                                    session.model.as_str(),
                                    session.turn,
                                    s.tool_calls,
                                    s.usage.input_tokens,
                                    s.usage.output_tokens,
                                    agent.max_turns(),
                                )
                            );
                        } else {
                            println!("No TurnSummary");
                        }
                        continue;
                    }
                    _ => {}
                }

                // Handle `/file <PATH>`: read the file's contents relative to
                // the working directory (or absolute) and use it as the prompt.
                // Only a single line can be typed at the REPL prompt, so this
                // lets multi-line content (a prompt, a plan, code) be loaded
                // from disk and sent to the model in one go.
                if let Some(rest) = line.strip_prefix("/file ") {
                    let path = rest.trim();
                    if path.is_empty() {
                        eprintln!("/file requires a path");
                        continue;
                    }
                    let content = match read_prompt_file(working_dir, path) {
                        Ok(c) => c,
                        Err(e) => {
                            eprintln!("error reading '{path}': {e}");
                            continue;
                        }
                    };
                    if content.trim().is_empty() {
                        eprintln!("/file '{path}' is empty");
                        continue;
                    }
                    println!(
                        "using contents of '{}' ({}, {} bytes) as prompt",
                        path,
                        cwd.display(),
                        content.len()
                    );
                    last_summary =
                        run_turn(session, &mut agent, provider, model_name, &content).await;
                    continue;
                }

                last_summary = run_turn(session, &mut agent, provider, model_name, &line).await;
            }
            Ok(Signal::CtrlC) | Ok(Signal::ExternalBreak(_)) => continue,
            Ok(Signal::CtrlD) => break,
            Ok(_) => continue,
            Err(e) => {
                eprintln!("readline error: {e}");
                break;
            }
        }
    }

    // Sync history to disk before shutting down.
    if let Err(e) = editor.sync_history() {
        eprintln!("warning: failed to sync history: {e}");
    }
    Ok(())
}

/// Run a single turn with the given prompt and stream the model's output.
async fn run_turn<M: CompletionModel + 'static>(
    session: &mut hanihi_core::session::Session,
    agent: &mut Agent<M>,
    provider: &str,
    model_name: &str,
    prompt: &str,
) -> Option<TurnSummary> {
    match session
        .run_streaming(agent, provider, model_name, prompt)
        .await
    {
        Ok(mut rx) => {
            while let Some(event) = rx.recv().await {
                match event {
                    StreamEvent::TextDelta { text } => print_coloured!("{text}"),
                    StreamEvent::ToolCallStart { name, .. } => print_coloured!("\n[🔧 {name}"),
                    StreamEvent::ToolCallArgs { .. } => {}
                    StreamEvent::ToolCallReady { .. } => {}
                    StreamEvent::ToolResult { .. } => println_coloured!(" ✅]"),
                    StreamEvent::CompletionRequest { .. }
                    | StreamEvent::CompletionResponse { .. } => {}
                    StreamEvent::TurnComplete { summary } => {
                        println!();
                        println_coloured!(
                            "[model: {} turn {} | tool calls: {} | tokens: {} in / {} out | max_turns: {}]",
                            session.model,
                            session.turn,
                            summary.tool_calls,
                            summary.usage.input_tokens,
                            summary.usage.output_tokens,
                            agent.max_turns()
                        );
                        // TODO: Do I need this `clone`?
                        agent.set_history(summary.final_history.clone());
                        return Some(summary);
                    }
                    StreamEvent::Error { message } => {
                        eprintln!();
                        eprintln!("error: {message}");
                        return None;
                    }
                }
            }
            None
        }
        Err(e) => {
            eprintln!("error: {e}");
            None
        }
    }
}

